import{_ as i,a0 as r,w as l,s,ao as d,I as o,x as e,a1 as p,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Python 调试技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Python 调试技巧 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 调试技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 调试技巧 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180519 Python Debugging Tips","title":"Python 调试技巧","tag":"201807","desc":""},"relativePath":"201807/20180519 Python Debugging Tips.md","filePath":"[post].md"}'),h={name:"201807/20180519 Python Debugging Tips.md"};function g(u,t,b,m,f,T){const a=r("Link");return l(),s("div",null,[t[15]||(t[15]=d('<h1 id="python-调试技巧" tabindex="-1">Python 调试技巧 <a class="header-anchor" href="#python-调试技巧" aria-label="Permalink to “Python 调试技巧”">​</a></h1><p>当进行调试时，你有很多选择，但是很难给出一直有效的通用建议（除了“你试过关闭再打开么？”以外）。</p><p>这里有一些我最喜欢的 Python 调试技巧。</p><h3 id="建立一个分支" tabindex="-1">建立一个分支 <a class="header-anchor" href="#建立一个分支" aria-label="Permalink to “建立一个分支”">​</a></h3><p>请相信我。即使你从来没有打算将修改提交回上游，你也会很乐意将你的实验被包含在它们自己的分支中。</p><p>不说别的，它会使清理更容易！</p><h3 id="安装-pdb" tabindex="-1">安装 pdb++ <a class="header-anchor" href="#安装-pdb" aria-label="Permalink to “安装 pdb++”">​</a></h3><p>认真地说，如果你使用命令行，它会让你的生活更轻松。</p><p>pdb++ 所做的一切就是用更好的模块替换标准的 pdb 模块。以下是你在 <code>pip install pdbpp</code> 会看到的：</p><ul><li>彩色提示！</li><li>制表符补全！（非常适合探索！）</li><li>支持切分！</li></ul><p>好的，也许最后一个是有点多余……但是非常认真地说，安装 pdb++ 非常值得。</p><h3 id="探索" tabindex="-1">探索 <a class="header-anchor" href="#探索" aria-label="Permalink to “探索”">​</a></h3><p>有时候最好的办法就是胡乱试试，然后看看会发生什么。在“明显”的位置放置一个断点并确保它被命中。在代码中加入 <code>print()</code> 和/或 <code>logging.debug()</code> 语句，并查看代码执行的位置。</p><p>检查传递给你的函数的参数，检查库的版本（如果你已经非常绝望了）。</p><h3 id="一次只能改变一件事" tabindex="-1">一次只能改变一件事 <a class="header-anchor" href="#一次只能改变一件事" aria-label="Permalink to “一次只能改变一件事”">​</a></h3><p>在你在探索了一下后，你将会对你可以做的事情有所了解。但在你开始摆弄代码之前，先退一步，考虑一下你可以改变什么，然后只改变一件事。</p><p>做出改变后，然后测试一下，看看你是否接近解决问题。如果没有，请将它改回来，然后尝试其他方法。</p><p>只更改一件事就可以让你知道什可以工作，哪些不工作。另外，一旦可以工作后，你的新提交将会小得多（因为将有更少的变化）。</p><p>这几乎是<ruby>科学过程<rt>Scientific Process</rt></ruby>中所做的事情：一次只更改一个变量。通过让自己看到并衡量一次更改的结果，你可以节省你的理智，并更快地找到解决方案。</p><h3 id="不要假设-提出问题" tabindex="-1">不要假设，提出问题 <a class="header-anchor" href="#不要假设-提出问题" aria-label="Permalink to “不要假设，提出问题”">​</a></h3><p>偶尔一个开发人员（当然不是你咯！）会匆忙提交一些有问题的代码。当你去调试这段代码时，你需要停下来，并确保你明白它想要完成什么。</p><p>不要做任何假设。仅仅因为代码在 <code>model.py</code> 文件中并不意味着它不会尝试渲染一些 HTML。</p><p>同样，在做任何破坏性的事情之前，仔细检查你的所有外部关联。要删除一些配置数据？<strong>请确保你没有连接到你的生产系统。</strong></p><h3 id="聪明-但不要聪明过头" tabindex="-1">聪明，但不要聪明过头 <a class="header-anchor" href="#聪明-但不要聪明过头" aria-label="Permalink to “聪明，但不要聪明过头”">​</a></h3><p>有时候我们编写的代码神奇般地奏效，不知道它是如何做的。</p><p>当我们发布代码时，我们可能会觉得自己很聪明，但当代码崩溃时，我们往往会感到愚蠢，我们必须记住它是如何工作的，以便弄清楚它为什么不起作用。</p><p>留意任何看起来过于复杂、冗长或极短的代码段。这些可能是隐藏复杂并导致错误的地方。</p><hr>',28)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),p(a,{href:"https://pythondebugging.com/articles/python-debugging-tips"},{default:n(()=>[...t[0]||(t[0]=[e("https://pythondebugging.com/articles/python-debugging-tips",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=e("作者：",-1)),p(a,{href:"https://pythondebugging.com"},{default:n(()=>[...t[2]||(t[2]=[e("PythonDebugging.com",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:n(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=e("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}co